import { build } from 'esbuild';
import { readdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const root = import.meta.dirname;
const outdir = path.join(root, 'dist');

const { metafile } = await build({
  absWorkingDir: root,
  entryPoints: ['sdk.mjs'],
  outfile: path.join(outdir, 'sdk.cjs'),
  bundle: true,
  platform: 'node',
  target: 'node24',
  format: 'cjs',
  minify: true,
  legalComments: 'none',
  metafile: true,
  logLevel: 'warning',
  banner: {
    js: '// Generated by build.mjs from pnpm-lock.yaml; run `pnpm run build` instead of editing.',
  },
});

// The bundle redistributes third-party code, so ship each bundled package's notices with it.
const packages = new Map();
for (const input of Object.keys(metafile.inputs)) {
  const match = input.match(/^(.*node_modules\/((?:@[^/]+\/)?[^/]+))\//);
  if (match) packages.set(match[2], match[1]);
}
const notices = [];
for (const [name, directory] of [...packages].sort(([a], [b]) => a.localeCompare(b))) {
  const { version, license } = JSON.parse(
    await readFile(path.join(root, directory, 'package.json'), 'utf8'),
  );
  const files = (await readdir(path.join(root, directory)))
    .filter((file) => /^(licen[cs]e|notice)/i.test(file))
    .sort();
  if (!files.length) throw new Error(`${name} has no license file to redistribute.`);
  notices.push(`${name}@${version} (${license})`);
  for (const file of files)
    notices.push((await readFile(path.join(root, directory, file), 'utf8')).trim());
}
await writeFile(path.join(outdir, 'THIRD_PARTY_NOTICES.txt'), `${notices.join('\n\n')}\n`);
